```csharp
// Provided: a binary tree node.
public class TreeNode {
    public int Value; public TreeNode Left, Right;
    public TreeNode(int value) { Value = value; }
}

// LeetCode 103 — values level by level, left-to-right, then right-to-left, alternating.
public static class Zigzag {
    public static IList<IList<int>> Levels(TreeNode root) {
        var result = new List<IList<int>>();
        if (root == null) return result;
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        bool leftToRight = true;
        while (queue.Count > 0) {
            int size = queue.Count;                      // exactly the nodes of this level
            var level = new List<int>(size);
            for (int k = 0; k < size; k++) {
                var node = queue.Dequeue();
                level.Add(node.Value);
                if (node.Left != null) queue.Enqueue(node.Left);
                if (node.Right != null) queue.Enqueue(node.Right);
            }
            if (!leftToRight) level.Reverse();           // visit in normal order, flip every other level
            result.Add(level);
            leftToRight = !leftToRight;
        }
        return result;
    }
}
```

